const poly=(c,pts,color)=>{c.fillStyle=color;c.beginPath();pts.forEach(([x,y],i)=>i?c.lineTo(x,y):c.moveTo(x,y));c.closePath();c.fill();};
const ellipse=(c,x,y,rx,ry,color)=>{c.fillStyle=color;c.beginPath();c.ellipse(x,y,rx,ry,0,0,Math.PI*2);c.fill();};
function cloud(c,x,y,s,alpha=1){c.save();c.globalAlpha=alpha;for(const [dx,dy,r] of [[-40,0,32],[0,-16,43],[40,0,30]])ellipse(c,x+dx*s,y+dy*s,r*s,26*s,'#edf5ff');c.restore();}
function palm(c,x,y){c.strokeStyle='#674b36';c.lineWidth=12;c.beginPath();c.moveTo(x,y);c.quadraticCurveTo(x-18,y-55,x+8,y-110);c.stroke();for(let i=0;i<6;i++){const a=-Math.PI+i*.6;c.strokeStyle=i%2?'#8fc77b':'#468a64';c.lineWidth=10;c.beginPath();c.moveTo(x+8,y-110);c.quadraticCurveTo(x+Math.cos(a)*35,y-140+Math.sin(a)*25,x+Math.cos(a)*65,y-95+Math.sin(a)*28);c.stroke();}}
export function drawBackdrop(c,m,t){
 if(m.id==='classic'){ellipse(c,1120,210,110,110,'#86a2ad12');for(let layer=0;layer<3;layer++){const pts=[[-300,1000]];for(let x=-300;x<=1700;x+=100)pts.push([x,470+layer*90+Math.sin(x*.006+layer*2)*75+Math.cos(x*.013)*35]);pts.push([1700,1000]);poly(c,pts,['#2c4555','#243c4a','#203441'][layer]);}}
 if(m.id==='desert'){ellipse(c,1100,200,78,78,'#ffdc9b');for(let l=0;l<3;l++){const pts=[[-200,900]];for(let x=-200;x<=1600;x+=80)pts.push([x,500+l*100+Math.sin(x*.004+l*1.8)*65]);pts.push([1600,900]);poly(c,pts,['#b7754a','#c68e57','#d0a369'][l]);}for(const x of [160,410,1080,1280]){c.strokeStyle='#526b4f';c.lineWidth=16;c.lineCap='round';c.beginPath();c.moveTo(x,710);c.lineTo(x,610);c.moveTo(x,660);c.lineTo(x-25,660);c.lineTo(x-25,630);c.moveTo(x,675);c.lineTo(x+25,675);c.lineTo(x+25,642);c.stroke();}}
 if(m.id==='island'){ellipse(c,1120,200,85,85,'#d5dfaa');for(let l=0;l<3;l++){const pts=[[-100,900]];for(let x=-100;x<=1500;x+=70)pts.push([x,600+l*60-Math.abs(Math.sin(x*.005+l))*125]);pts.push([1500,900]);poly(c,pts,['#376b5e','#315f53','#2b524b'][l]);}for(const [x,y] of [[170,700],[795,700],[1230,700]])palm(c,x,y);}
 if(m.id==='cloud'){for(let i=0;i<15;i++)cloud(c,((i*213+t*(i%2?8:-5))%1700+1700)%1700-150,130+(i*137)%650,.6+(i%3)*.7,.22+(i%3)*.15);ellipse(c,1160,130,60,60,'#fff2bd');}
 if(m.id==='volcano'){ellipse(c,1110,190,80,80,'#e9996940');poly(c,[[100,850],[540,240],[680,220],[1160,850]],'#392c3d');poly(c,[[540,240],[580,295],[630,260],[680,220],[630,225],[580,230]],'#ff925b');poly(c,[[585,260],[610,330],[600,400],[655,475],[650,600],[680,700],[715,850],[755,850],[680,590],[687,465],[640,385],[650,290]],'#d4553e');for(let i=0;i<9;i++)ellipse(c,590+Math.sin(i)*30,230-((i*47+t*22)%270),30+i*3,20+i*3,'#9a6e7040');for(let i=0;i<35;i++){c.fillStyle='#ffa26488';c.fillRect((i*193+t*13)%1400,850-(i*71+t*40)%850,3,5);}c.fillStyle='#e85834';c.fillRect(0,m.lava,1400,140);for(let i=0;i<30;i++)ellipse(c,(i*53+t*18)%1450,m.lava+15+Math.sin(i+t)*10,24,4,'#ffbf5e');}
 if(m.id==='city'){ellipse(c,1120,170,65,65,'#e8dcff');for(let l=0;l<2;l++)for(let i=0;i<16;i++){const x=i*105-l*40,y=330+((i*73+l*29)%230);c.fillStyle=l?'#27334d':'#252b44';c.fillRect(x,y,85,900-y);for(let wy=y+20;wy<850;wy+=32)for(let wx=x+12;wx<x+70;wx+=25)if((i+wx+wy)%7>2){c.fillStyle=(i+wy)%3?'#bcd9d544':'#ffa8d366';c.fillRect(wx,wy,9,13);}}}
 if(m.id==='ocean'){ellipse(c,1120,170,75,75,'#f4e1ac');for(let i=0;i<7;i++)cloud(c,(i*259+t*4)%1650-100,160+(i%3)*90,.65,.3);c.fillStyle='#205a7c';c.fillRect(0,610,1400,240);for(let j=0;j<8;j++){c.strokeStyle=j%2?'#7bc2d54d':'#e6f7ff33';c.lineWidth=2;c.beginPath();for(let x=-50;x<=1450;x+=12){const y=625+j*29+Math.sin(x*.025+t*1.7+j)*4;x===-50?c.moveTo(x,y):c.lineTo(x,y);}c.stroke();}c.fillStyle='#164969';c.fillRect(0,m.water,1400,150);}
}
export function drawTerrain(c,m,platforms,t){for(const p of platforms){c.fillStyle='#111e293a';c.fillRect(p.x+8,p.y+13,p.w,p.h);c.fillStyle=m.rock;c.fillRect(p.x,p.y,p.w,p.h);c.fillStyle=m.top;c.fillRect(p.x,p.y,p.w,8);c.fillStyle=m.light;c.fillRect(p.x,p.y,p.w,3);
 if(m.id==='ocean'){for(let x=p.x+8;x<p.x+p.w;x+=24){c.strokeStyle='#3f3028';c.lineWidth=2;c.strokeRect(x,p.y+4,19,p.h-5);}for(const x of [p.x+18,p.x+p.w-18]){c.fillStyle='#e8d3a0';c.fillRect(x,p.y,5,p.h);}continue;}
 if(m.id==='cloud'){for(let x=p.x+18;x<p.x+p.w;x+=40)ellipse(c,x,p.y+p.h-4,25,13,'#d8e5f5');continue;}
 if(m.id==='city'){for(let x=p.x+12;x<p.x+p.w-10;x+=30)for(let y=p.y+20;y<p.y+p.h-8;y+=28){c.fillStyle=((x+y)%3)?'#8de8e960':'#ffc7dc60';c.fillRect(x,y,12,14);}c.fillStyle='#111d33';c.fillRect(p.x,p.y+9,p.w,5);continue;}
 for(let x=p.x;x<p.x+p.w;x+=40){c.fillStyle='#ffffff0b';c.fillRect(x+1,p.y+12,Math.min(36,p.x+p.w-x-1),Math.min(p.h-13,28));c.strokeStyle='#10203235';c.strokeRect(x,p.y+9,Math.min(40,p.x+p.w-x),p.h-9);}if(p.h>40)poly(c,[[p.x,p.y+p.h],[p.x+p.w*.2,p.y+p.h+35],[p.x+p.w*.5,p.y+p.h+65],[p.x+p.w*.8,p.y+p.h+30],[p.x+p.w,p.y+p.h]],m.rock);
 if(m.id==='volcano'){c.strokeStyle='#ff8454';c.lineWidth=2;c.beginPath();c.moveTo(p.x+p.w*.3,p.y+14);c.lineTo(p.x+p.w*.4,p.y+22);c.lineTo(p.x+p.w*.35,p.y+p.h);c.stroke();}}
}
export function drawWater(c,m,t){if(m.water===undefined)return;c.save();c.fillStyle='#52b6cf30';c.fillRect(0,m.water,1400,150);c.strokeStyle='#aeefff';c.lineWidth=3;c.beginPath();for(let x=0;x<=1400;x+=10){const y=m.water+Math.sin(x*.035+t*3)*3;x?c.lineTo(x,y):c.moveTo(x,y);}c.stroke();c.fillStyle='#d7faff';c.font='700 16px Barlow,Arial';c.textAlign='center';c.fillText('HOLD L TO SWIM · A / D TO STEER · SPACE TO LEAP ONTO A RAFT',700,820);c.restore();}
